# ============================================================
# STEP 12 — HOURLY GAPS
# ============================================================

gap_results = []

for station, group in df.groupby("Station"):

    times = (
        group["timestamp"]
        .sort_values()
        .drop_duplicates()
    )

    differences = times.diff().dropna()

    gaps = (differences > pd.Timedelta(hours=1)).sum()

    gap_results.append({
        "Station": station,
        "Hourly_Gaps": gaps,
        "Largest_Gap": differences.max()
    })

gap_df = pd.DataFrame(gap_results)

display(gap_df)

