import pandas as pd
import numpy as np

print("=" * 75)
print("CPCB-STYLE AQI CALCULATION")
print("=" * 75)


# ============================================================
# STEP 13 — CPCB AQI BREAKPOINTS
# ============================================================

AQI_BREAKPOINTS = {

    "PM2.5": [
        (0, 30, 0, 50),
        (31, 60, 51, 100),
        (61, 90, 101, 200),
        (91, 120, 201, 300),
        (121, 250, 301, 400),
        (251, float("inf"), 401, 500)
    ],

    "PM10": [
        (0, 50, 0, 50),
        (51, 100, 51, 100),
        (101, 250, 101, 200),
        (251, 350, 201, 300),
        (351, 430, 301, 400),
        (431, float("inf"), 401, 500)
    ],

    "NO2": [
        (0, 40, 0, 50),
        (41, 80, 51, 100),
        (81, 180, 101, 200),
        (181, 280, 201, 300),
        (281, 400, 301, 400),
        (401, float("inf"), 401, 500)
    ],

    "SO2": [
        (0, 40, 0, 50),
        (41, 80, 51, 100),
        (81, 380, 101, 200),
        (381, 800, 201, 300),
        (801, 1600, 301, 400),
        (1601, float("inf"), 401, 500)
    ],

    "Ozone": [
        (0, 50, 0, 50),
        (51, 100, 51, 100),
        (101, 168, 101, 200),
        (169, 208, 201, 300),
        (209, 748, 301, 400),
        (749, float("inf"), 401, 500)
    ],

    "NH3": [
        (0, 200, 0, 50),
        (201, 400, 51, 100),
        (401, 800, 101, 200),
        (801, 1200, 201, 300),
        (1201, 1800, 301, 400),
        (1801, float("inf"), 401, 500)
    ],

    "CO": [
        (0, 1.0, 0, 50),
        (1.1, 2.0, 51, 100),
        (2.1, 10.0, 101, 200),
        (10.1, 17.0, 201, 300),
        (17.1, 34.0, 301, 400),
        (34.1, float("inf"), 401, 500)
    ]
}


def calculate_subindex(concentration, pollutant):

    if pd.isna(concentration):
        return np.nan

    for c_low, c_high, i_low, i_high in AQI_BREAKPOINTS[pollutant]:

        if c_low <= concentration <= c_high:

            subindex = (
                ((i_high - i_low) /
                 (c_high - c_low))
                * (concentration - c_low)
                + i_low
            )

            return subindex

    return np.nan


print("AQI breakpoint table loaded.")


