print("Pollutant sub-indices calculated.")
print("Overall AQI calculated.")


# ============================================================
# STEP 16 — AQI CATEGORY
# ============================================================

print("\n" + "=" * 75)
print("CREATING AQI CATEGORIES")
print("=" * 75)


def aqi_category(aqi):

    if pd.isna(aqi):
        return "Missing"

    elif aqi <= 50:
        return "Good"

    elif aqi <= 100:
        return "Satisfactory"

    elif aqi <= 200:
        return "Moderate"

    elif aqi <= 300:
        return "Poor"

    elif aqi <= 400:
        return "Very Poor"

    else:
        return "Severe"


df["AQI_Category"] = df["AQI"].apply(aqi_category)


