# ---------------------------------------------------------------------------

persistence = comparison_df[
    comparison_df["Model"] == "Persistence"
].iloc[0]

comparison_df["R2_Improvement"] = (
    comparison_df["Test_R2"] - persistence["Test_R2"]
)

comparison_df["MAE_Reduction"] = (
    persistence["Test_MAE"] - comparison_df["Test_MAE"]
)

comparison_df["RMSE_Reduction"] = (
    persistence["Test_RMSE"] - comparison_df["Test_RMSE"]
)

comparison_df["Beats_Persistence"] = (
    (comparison_df["Test_R2"] > persistence["Test_R2"]) &
    (comparison_df["Test_MAE"] < persistence["Test_MAE"]) &
    (comparison_df["Test_RMSE"] < persistence["Test_RMSE"])
)

