# ============================================================================
# STEP 36D — EXACT METRICS FOR EXISTING TRAINED MODELS
# ============================================================================

from sklearn.metrics import r2_score, mean_absolute_error, mean_squared_error
import numpy as np
import pandas as pd

print("=" * 90)
print("STEP 36D — EXACT TEST METRICS")
print("=" * 90)


def evaluate_model(name, model, X, y):
    """
    Predict using an already-trained model and calculate
    R², MAE and RMSE.
    """

    predictions = model.predict(X)

    r2 = r2_score(y, predictions)
    mae = mean_absolute_error(y, predictions)
    rmse = np.sqrt(mean_squared_error(y, predictions))

    print(f"\n{name}")
    print("-" * 60)
    print(f"Samples : {len(y)}")
    print(f"R²      : {r2:.6f}")
    print(f"MAE     : {mae:.6f}")
    print(f"RMSE    : {rmse:.6f}")

    return {
        "Model": name,
        "Test_R2": r2,
        "Test_MAE": mae,
        "Test_RMSE": rmse,
        "Samples": len(y)
    }


recovered_results = []


# ---------------------------------------------------------------------------
# 1. TUNED RANDOM FOREST
# ---------------------------------------------------------------------------

recovered_results.append(
    evaluate_model(
        "Tuned Random Forest",
        best_rf,
        X_test_full,
        y_test_full
    )
)


# ---------------------------------------------------------------------------
# 2. TEMPORAL RANDOM FOREST
# ---------------------------------------------------------------------------

recovered_results.append(
    evaluate_model(
        "Temporal Random Forest",
        temporal_rf,
        X_test_temporal,
        y_test_temporal
    )
)


# ---------------------------------------------------------------------------
# 3. ONE-HOUR FORECAST RANDOM FOREST
# ---------------------------------------------------------------------------

recovered_results.append(
    evaluate_model(
        "One-Hour Forecast RF",
        forecast_rf,
        X_test_forecast,
        y_test_forecast
    )
)


# ---------------------------------------------------------------------------
# 4. AQI-HISTORY RANDOM FOREST
# ---------------------------------------------------------------------------

recovered_results.append(
    evaluate_model(
        "AQI-History RF",
        aqi_history_rf,
        X_test_aqif,
        y_test_aqif
    )
)


# ---------------------------------------------------------------------------
# 5. STEP 35 FINAL MODEL
# ---------------------------------------------------------------------------

recovered_results.append(
    evaluate_model(
        "Step 35 Final RF",
        final_model,
        X_test_final[
            final_model.feature_names_in_
        ],
        y_test_aqif
    )
)


# ---------------------------------------------------------------------------
# CREATE DATAFRAME
# ---------------------------------------------------------------------------

recovered_df = pd.DataFrame(recovered_results)

print("\n" + "=" * 90)
print("RECOVERED MODEL RESULTS")
