# ============================================================================
# STEP 36H — COMMON TEST-SET PREDICTIONS  [SUPERSEDED]
# ============================================================================
#
# NOTE: This attempt tries to align test_temporal (target = CURRENT-hour AQI,
# built in STEP 27) with test_ab (target = NEXT-hour AQI / "AQI_next_1h",
# built for the ablation study) on Station + DateTime, then asserts their
# targets are identical. They are not — they are answers to two different
# questions (nowcasting vs. one-hour-ahead forecasting) — so the strict
# equality check below correctly (if confusingly) fails on real data.
#
# The next cell (also STEP 36H) is the corrected version: it drops the
# mismatched Temporal RF model entirely and compares only All-Temporal RF vs.
# Persistence, both computed from the same test_ab dataset, avoiding the
# cross-target mismatch. This cell is kept only for narrative continuity and
# intentionally does no computation.
# ============================================================================

print("STEP 36H (first attempt) skipped — test_temporal and test_ab use")
print("different targets (current-hour vs next-hour AQI) and cannot be")
print("validly compared this way. See the corrected STEP 36H cell below,")
print("which compares All-Temporal RF vs Persistence on a single consistent")
print("test set (test_ab).")

# ============================================================================
# STEP 36H — ALL-TEMPORAL VS PERSISTENCE
# COMMON TEST SET
# ============================================================================

import pandas as pd
import numpy as np

from sklearn.metrics import (
    r2_score,
    mean_absolute_error,
    mean_squared_error
)

print("=" * 100)
print("STEP 36H — ALL-TEMPORAL VS PERSISTENCE")
print("=" * 100)


# ---------------------------------------------------------------------------
# 1. Locate fitted All-Temporal model
# ---------------------------------------------------------------------------

print("\nAvailable ablation models:")
print(list(ablation_models.keys()))

all_temporal_model = None
all_temporal_name = None

for key, model in ablation_models.items():

    # Check whether the model is fitted
    if hasattr(model, "feature_names_in_"):

        if (
            "E" in str(key)
            or "All" in str(key)
            or "Temporal" in str(key)
        ):

            all_temporal_model = model
            all_temporal_name = key
            break

if all_temporal_model is None:
    raise ValueError(
        "Fitted All-Temporal model was not found."
    )

print(
    "\nSelected model:",
    all_temporal_name
)

print(
    "Training features:",
    len(all_temporal_model.feature_names_in_)
)


# ---------------------------------------------------------------------------
# 2. Generate All-Temporal predictions
# ---------------------------------------------------------------------------

features = list(
    all_temporal_model.feature_names_in_
)

all_temporal_pred = all_temporal_model.predict(
    X_test_ab[features]
)

print(
    "All-Temporal predictions:",
    len(all_temporal_pred)
)


# ---------------------------------------------------------------------------
# 3. Build prediction dataframe
# ---------------------------------------------------------------------------

comparison = pd.DataFrame({

    "Station": test_ab["Station"].values,

    "DateTime": pd.to_datetime(
        test_ab["DateTime"].values
    ),

    "Actual_AQI": y_test_ab.values,

    "All_Temporal_RF": all_temporal_pred,

    "Persistence": test_ab["AQI"].values
})


# ---------------------------------------------------------------------------
# 4. Verify persistence
# ---------------------------------------------------------------------------

print("\nChecking persistence definition...")

print(
    "Persistence = current AQI → next-hour AQI"
)

print(
    "Maximum difference between persistence and current AQI:",
    np.max(
        np.abs(
            comparison["Persistence"]
            -
            test_ab["AQI"].values
        )
    )
)


# ---------------------------------------------------------------------------
# 5. Metrics
# ---------------------------------------------------------------------------

def metrics(y, pred):

    return {
        "R2": r2_score(y, pred),
        "MAE": mean_absolute_error(y, pred),
        "RMSE": np.sqrt(
            mean_squared_error(y, pred)
        )
    }


y = comparison["Actual_AQI"].values

all_temporal_metrics = metrics(
    y,
    comparison["All_Temporal_RF"].values
)

persistence_metrics = metrics(
    y,
    comparison["Persistence"].values
)


# ---------------------------------------------------------------------------
# 6. Display
# ---------------------------------------------------------------------------

common_results = pd.DataFrame([
    {
        "Model": "All-Temporal RF",
        **all_temporal_metrics
    },

    {
        "Model": "Persistence",
        **persistence_metrics
    }
])

print("\n" + "=" * 100)
print("COMMON TEST-SET RESULTS")
print("=" * 100)

display(
    common_results.style.format({
        "R2": "{:.6f}",
        "MAE": "{:.6f}",
        "RMSE": "{:.6f}"
    })
)


# ---------------------------------------------------------------------------
# 7. Calculate improvements
# ---------------------------------------------------------------------------

print("\n" + "=" * 100)
print("ALL-TEMPORAL IMPROVEMENT OVER PERSISTENCE")
print("=" * 100)

print(
    "R² improvement:",
    all_temporal_metrics["R2"]
    -
    persistence_metrics["R2"]
)

print(
    "MAE reduction:",
    persistence_metrics["MAE"]
    -
    all_temporal_metrics["MAE"]
)

print(
    "RMSE reduction:",
    persistence_metrics["RMSE"]
    -
    all_temporal_metrics["RMSE"]
)


# ---------------------------------------------------------------------------
# 8. Save predictions
# ---------------------------------------------------------------------------

comparison.to_csv(
    "STEP36H_all_temporal_vs_persistence_predictions.csv",
    index=False
)

common_results.to_csv(
    "STEP36H_all_temporal_vs_persistence_results.csv",
    index=False
)

print("\nSaved:")
print(
    "STEP36H_all_temporal_vs_persistence_predictions.csv"
)

print(
    "STEP36H_all_temporal_vs_persistence_results.csv"
)

print("\n" + "=" * 100)
print("STEP 36H COMPLETE")
